import{_ as a,o as t,c as o,a8 as i}from"./chunks/framework.CNIpabDg.js";const u=JSON.parse('{"title":"About","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md","lastUpdated":1792103082000}'),r={name:"about/index.md"};function s(n,e,d,l,p,c){return t(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792103082000"},[...e[0]||(e[0]=[i('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p>Xila is an open-source operating system designed for embedded systems. It aims to provide a modular, portable, and efficient platform for developing applications in the embedded world.</p><h2 id="mission" tabindex="-1">Mission <a class="header-anchor" href="#mission" aria-label="Permalink to &quot;Mission&quot;">​</a></h2><p>Our mission is to create a versatile operating system that can run on a wide range of hardware platforms, from microcontrollers to desktop computers. We strive to make Xila user-friendly, flexible, and adaptable to various use cases in the embedded domain.</p><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><p>We envision a future where Xila becomes the go-to operating system for embedded developers, fostering innovation and collaboration within the community. By providing a robust and scalable platform, we aim to empower developers to create cutting-edge applications that push the boundaries of embedded technology.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Xila is developed by <a href="https://alix.anneraud.fr" target="_blank" rel="noreferrer">Alix ANNERAUD</a>. It is released under the <a href="https://www.apache.org/licenses/LICENSE-2.0" target="_blank" rel="noreferrer">Apache License 2.0</a>, allowing users to use, modify, and distribute the software under its terms.</p>',8)])])}const h=a(r,[["render",s]]);export{u as __pageData,h as default};
